	@Test
	void incrementalOrderCarriesOutputColumnPositions() {
		PositionHooks hooks = new PositionHooks();
		try (KernelOrderSink sink = new KernelOrderSink(2, new int[] { 1 }, null, hooks, null, 0, -1)) {
			sink.add(new long[] { 10, 7 });
			sink.add(new long[] { 20, 3 });
			sink.finish();
			long[] result = new long[4];
			assertThat(sink.fill(result, 2)).isEqualTo(2);
			assertThat(result).containsExactly(20, 3, 10, 7);
			assertThat(hooks.comparisons).isPositive();
		}
	}

